#!/usr/bin/env node
/**
 * Copies the approved design (design/monitoring-ui) into the app. The copies are
 * generated files: change the design, then run `pnpm --filter @skilllane/monitoring-monitor sync-design`.
 *
 *   assets/styles.css      → app/design-system.css      (tokens + components, imported by app/layout.tsx)
 *   assets/system-map.js   → lib/3d/system-map.js       (three.js module; CDN imports rewritten to `three`)
 *   assets/system-map.css  → lib/3d/system-map.css
 *   docs/DATA-DICTIONARY.md → public/DATA-DICTIONARY.md (sidebar "พจนานุกรมข้อมูล")
 *
 * lib/3d/system-map.d.ts is hand-written from the module's exports. When it is missing,
 * a loose one is generated from the export names so the app still type-checks.
 * assets/app.js is not copied: its behaviours are ported to React (components/).
 *
 * APP_PATCHES below are fixes to the 3D module that the app needs before the design has
 * them. Each is applied on every sync; once the design contains it the patch is skipped
 * (and should be deleted here), and a patch that no longer matches stops the sync.
 */
import { existsSync } from 'node:fs'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const app = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const repo = resolve(app, '../..')
const assets = resolve(repo, 'design/monitoring-ui/assets')

const rel = (p) => relative(repo, p)
const header = (src, comment) =>
  comment(`GENERATED by apps/monitor/scripts/sync-design.mjs from ${rel(src)}. Do not edit: change the design, then run \`pnpm --filter @skilllane/monitoring-monitor sync-design\`.`)
const cssComment = (text) => `/* ${text} */\n`
const jsComment = (text) => `// ${text}\n`

/**
 * Fixes on top of the design's module (file: 'js' = system-map.js after the three.js rewrite, 'css' = system-map.css).
 * `find` must occur exactly once; `replace` replaces it. Hand these to the design owner, then delete them.
 */
const APP_PATCHES = [
  {
    // review overview-4: in a compact box (< 560 px or compactLabels) two- and three-line labels of the failing
    // services took the room, so failing dependencies (Oracle, Google Sheets, ThaID) next to the callouts lost
    // their label while healthy one-line ones still fitted. A node that is not ok now gets one line there:
    // name · error % (or its state); the full numbers stay in the tooltip, aria-label and the full-size label.
    name: 'compact-failing-labels',
    file: 'js',
    find: `    bits.forEach((b, i) => { if (i) meta.appendChild(document.createTextNode(' · ')); meta.appendChild(b); });
    node.replaceChildren(nameEl);`,
    replace: `    bits.forEach((b, i) => { if (i) meta.appendChild(document.createTextNode(' · ')); meta.appendChild(b); });
    if (n.state !== 'ok') {
      // compact box: one line (shown by system-map.css instead of the meta line)
      const short = el('span', 'smap__label-short', n.state === 'down' ? STATE_TEXT.down : errShown ? fmtPct(n.errorRate) : STATE_TEXT[n.state]);
      const tone = errTone(n);
      if (tone) short.dataset.tone = tone;
      nameEl.appendChild(short);
    }
    node.replaceChildren(nameEl);`,
  },
  {
    name: 'compact-failing-labels',
    file: 'css',
    find: `.smap--names .smap__label[data-state="ok"]:not(.smap__label--station) .smap__label-meta { display: none; }
`,
    replace: `.smap--names .smap__label[data-state="ok"]:not(.smap__label--station) .smap__label-meta { display: none; }
/* …and a node that is not ok keeps one line, name · error % (or its state), so failing nodes fit first */
.smap__label-short { display: none; }
.smap--compact .smap__label:not([data-state="ok"]):not(.smap__label--station) .smap__label-meta,
.smap--names .smap__label:not([data-state="ok"]):not(.smap__label--station) .smap__label-meta { display: none; }
.smap--compact .smap__label:not([data-state="ok"]) .smap__label-short,
.smap--names .smap__label:not([data-state="ok"]) .smap__label-short { display: inline; font-family: var(--font-mono, ui-monospace, monospace); font-size: 11px; font-weight: 600; font-variant-numeric: tabular-nums; }
.smap__label-short::before { content: "· "; color: var(--muted, #696969); font-weight: 400; }
.smap__label-short[data-tone="danger"] { color: var(--danger, #b71727); }
.smap__label-short[data-tone="warn"] { color: var(--warn, #7a5000); }
`,
  },
  {
    // review overview-4 (second round): at 1440 the compact box (524×298) still left school-core-api/worker (ต้องดู
    // 17.6 %) and school-etl-api/api without a label while healthy cron, Kafka and AWS S3 kept theirs: all four spots
    // next to the worker were taken by higher-priority failing labels, and the greedy pass then gave the room to
    // healthy ones further away. Now (1) in a compact box (< 560 px or compactLabels) healthy queues, databases and
    // outside APIs get no label at all (dropCompact; name in the tooltip and the tables; a row hover still shows it),
    // and (2) a node that is not ok (must) that finds no room next to its shape takes the nearest free spot further
    // out (rings of label height / half width, up to 4 steps) with a leader line back to the shape.
    name: 'label-priority',
    file: 'js',
    find: `    const placed = blocked.slice();
    const W = size.w, H = size.h;
    let d = '';
    for (const l of sortedLabels) {
      if (!l.w) { l.w = l.el.offsetWidth; l.h = l.el.offsetHeight; }`,
    replace: `    const placed = blocked.slice();
    const W = size.w, H = size.h;
    // compact box: labels flagged dropCompact (healthy infrastructure) are left out, unless pinned (hover, highlight)
    const compact = root.classList.contains('smap--compact') || root.classList.contains('smap--names');
    const hits = (cr) => {
      for (let i = 0; i < placed.length; i++) { const p = placed[i]; if (cr[0] < p[2] && cr[2] > p[0] && cr[1] < p[3] && cr[3] > p[1]) return true; }
      return false;
    };
    let d = '';
    for (const l of sortedLabels) {
      if (compact && l.dropCompact && !l.pinned) {
        if (l.hidden !== true) { l.el.classList.add('is-hidden'); l.hidden = true; }
        continue;
      }
      if (!l.w) { l.w = l.el.offsetWidth; l.h = l.el.offsetHeight; }`,
  },
  {
    name: 'label-priority',
    file: 'js',
    find: `      if (off || l.suppressed === true) hide = true;
      if (!hide) placed.push(r);
      if (!hide && l.align === 'above' && l.cand && l.cand !== 'above') {`,
    replace: `      // a node that is not ok is never crowded out: the nearest free spot further out, with a leader line
      if (hide && l.must && !off && l.suppressed !== true) {
        const far = farSpot(l, px, py, W, H, hits);
        if (far) { x = far[0]; y = far[1]; r = far[2]; hide = false; l.cand = 'far'; }
      }
      if (off || l.suppressed === true) hide = true;
      if (!hide) placed.push(r);
      if (!hide && l.cand === 'far') {
        const lx = clamp(px, x, x + l.w), ly = py < y ? y : py > y + l.h ? y + l.h : y + l.h / 2;
        d += 'M' + Math.round(lx) + ' ' + Math.round(ly) + 'L' + Math.round(px) + ' ' + Math.round(py);
      } else if (!hide && l.align === 'above' && l.cand && l.cand !== 'above') {`,
  },
  {
    name: 'label-priority',
    file: 'js',
    find: `  /** Overlays (toolbar, legend, top bar) are kept free of labels. */
  function measureOverlays() {`,
    replace: `  /**
   * A spot for a label that must show (l.must) when the four next to its shape are taken: rings around the anchor,
   * nearest first, steps of the label's height up / down and half its width sideways (up to 4 steps); the spot
   * that fitted last time is tried first, so the label does not jump while the view turns. null when none is free.
   */
  function farSpot(l, px, py, W, H, hits) {
    const stepX = l.w / 2 + 10, stepY = l.h + 4;
    const tries = l.far ? [l.far] : [];
    for (let k = 1; k <= 4; k++) tries.push([0, -k], [0, k], [-k, -k], [k, -k], [-k, k], [k, k], [-k, 0], [k, 0]);
    for (const t of tries) {
      const cx = clamp(px - l.w / 2 + t[0] * stepX, 4, Math.max(4, W - l.w - 4));
      const cy = clamp(py - l.h - 6 + t[1] * stepY, 4, Math.max(4, H - l.h - 4));
      const cr = [cx - 3, cy - 2, cx + l.w + 3, cy + l.h + 2];
      if (!hits(cr)) { l.far = t; return [cx, cy, cr]; }
    }
    return null;
  }
  /** Overlays (toolbar, legend, top bar) are kept free of labels. */
  function measureOverlays() {`,
  },
  {
    name: 'label-priority',
    file: 'js',
    find: `  function errTone(n) { return n.state === 'down' || n.state === 'error' ? 'danger' : (n.state === 'warn' || n.state === 'degraded') ? 'warn' : ''; }`,
    replace: `  function errTone(n) { return n.state === 'down' || n.state === 'error' ? 'danger' : (n.state === 'warn' || n.state === 'degraded') ? 'warn' : ''; }
  // label placement flags: a node that is not ok must show; healthy infrastructure (the quiet name-only labels of
  // fillNodeLabel) is dropped in a compact box, so every failing node has room first
  function mustLabel(n) { return n.state !== 'ok'; }
  function dropInCompact(n) { return n.state === 'ok' && !n.note && (n.kind === 'queue' || n.kind === 'dependency' || n.kind === 'external'); }`,
  },
  {
    name: 'label-priority',
    file: 'js',
    find: `      el: node, priority: pr, align: 'above', world: new THREE.Vector3(),`,
    replace: `      el: node, priority: pr, align: 'above', world: new THREE.Vector3(), must: mustLabel(rec.n), dropCompact: dropInCompact(rec.n),`,
  },
  {
    name: 'label-priority',
    file: 'js',
    find: `        rec.label.priority = (STATE_RANK[n.state] || 0) * 10 + ({ service: 6, worker: 5, queue: 4 }[n.kind] || 3) + Math.log10(1 + n.rpm) * 0.3;`,
    replace: `        rec.label.priority = (STATE_RANK[n.state] || 0) * 10 + ({ service: 6, worker: 5, queue: 4 }[n.kind] || 3) + Math.log10(1 + n.rpm) * 0.3;
        rec.label.must = mustLabel(n);
        rec.label.dropCompact = dropInCompact(n);`,
  },
  {
    // review overview-5: on phones the legend summary ("อ่านภาพนี้อย่างไร") and the toolbar covered the bottom ~20 %
    // of the canvas, and an open legend ~60 %. Under 600 px the map's root is a grid: the stage (canvas + labels) on
    // top, the legend summary and the toolbar in a row under it; an open legend takes room from the stage (the scene
    // refits) instead of covering it. The stage, not the root, now sets the renderer size.
    name: 'phone-overlays-below',
    file: 'js',
    find: `    const w = Math.round(root.clientWidth), h = Math.round(root.clientHeight);`,
    replace: `    // the stage, not the root: on phones the legend and the toolbar sit in a row under it (system-map.css)
    const w = Math.round(stageEl.clientWidth), h = Math.round(stageEl.clientHeight);`,
  },
  {
    name: 'phone-overlays-below',
    file: 'js',
    find: `  if (ro) ro.observe(root); else window.addEventListener('resize', resize);`,
    replace: `  if (ro) { ro.observe(root); ro.observe(stageEl); } else window.addEventListener('resize', resize);`,
  },
  {
    name: 'phone-overlays-below',
    file: 'css',
    find: `.smap--compact .smap__legend { max-width: calc(100% - 20px); bottom: 54px; }
`,
    replace: `.smap--compact .smap__legend { max-width: calc(100% - 20px); bottom: 54px; }
/* phones: the legend summary and the toolbar sit in a row under the canvas, never over it; an open legend takes room
   from the canvas (the scene refits). The module sizes the renderer from .smap__stage. */
@media (max-width: 600px) {
  .smap--map { display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-rows: minmax(0, 1fr) auto; }
  .smap--map > .smap__stage, .smap--map > .smap__labels { position: relative; inset: auto; grid-area: 1 / 1 / 2 / 3; min-height: 0; }
  .smap--map > .smap__legend { position: static; grid-area: 2 / 1; align-self: start; max-width: none; max-height: 220px; overflow: auto; margin: 8px 8px 0 0; }
  .smap--map > .smap__toolbar { position: static; grid-area: 2 / 2; align-self: start; margin-top: 8px; }
}
`,
  },
]

/** Applies the APP_PATCHES of `file` to `text`; a patch the design already has is skipped. */
function applyPatches(file, text) {
  let out = text
  for (const p of APP_PATCHES.filter((x) => x.file === file)) {
    const n = out.split(p.find).length - 1
    if (n === 1) {
      out = out.replace(p.find, () => p.replace)
      console.log(`[sync-design] app patch ${p.name} (${file}) applied`)
    } else if (out.includes(p.replace)) {
      console.log(`[sync-design] app patch ${p.name} (${file}) is in the design already: delete it from APP_PATCHES`)
    } else {
      throw new Error(`[sync-design] app patch ${p.name} (${file}) no longer matches the design (found ${n}×): update or drop it in scripts/sync-design.mjs`)
    }
  }
  return out
}
const patchedNote = (file) => (APP_PATCHES.some((p) => p.file === file) ? ' App patches (APP_PATCHES in the script) are applied on top.' : '')

async function write(dest, text) {
  await mkdir(dirname(dest), { recursive: true })
  await writeFile(dest, text)
  console.log(`[sync-design] ${rel(dest)} (${Buffer.byteLength(text).toLocaleString('en-US')} bytes)`)
}

/** styles.css: next/font loads the fonts, so a Google Fonts @import is dropped. */
async function syncStyles() {
  const src = resolve(assets, 'styles.css')
  const css = (await readFile(src, 'utf8')).replace(/@import\s+url\(["']?https:\/\/fonts\.googleapis\.com[^)]*\)\s*;?\n?/g, '')
  await write(resolve(app, 'app/design-system.css'), header(src, cssComment) + css)
}

/**
 * three.js from a CDN URL → the installed `three` package. Bare specifiers ('three',
 * 'three/addons/…', mapped by an importmap in the mockups) resolve from npm as they are.
 */
function rewriteThreeImports(js) {
  return js
    .replace(/(['"])https?:\/\/[^'"]*three@[\d.]+\/build\/three\.module(?:\.min)?\.js\1/g, "'three'")
    .replace(/(['"])https?:\/\/[^'"]*three@[\d.]+\/examples\/jsm\/([^'"]+)\1/g, "'three/addons/$2'")
}

/** Export names of an ES module (function, class, const/let, `export { a, b as c }`, default). */
function exportNames(js) {
  const names = new Map()
  for (const m of js.matchAll(/^export\s+(?:async\s+)?function\s*\*?\s*([A-Za-z_$][\w$]*)/gm)) names.set(m[1], 'function')
  for (const m of js.matchAll(/^export\s+class\s+([A-Za-z_$][\w$]*)/gm)) names.set(m[1], 'class')
  for (const m of js.matchAll(/^export\s+(?:const|let|var)\s+([A-Za-z_$][\w$]*)/gm)) names.set(m[1], 'value')
  for (const m of js.matchAll(/^export\s*\{([^}]*)\}/gm)) {
    for (const part of m[1].split(',')) {
      const name = part.trim().split(/\s+as\s+/).pop()?.trim()
      if (name) names.set(name, names.get(name) ?? 'value')
    }
  }
  const hasDefault = /^export\s+default\b/m.test(js)
  return { names, hasDefault }
}

function looseDts(js) {
  const { names, hasDefault } = exportNames(js)
  const lines = [
    '// GENERATED placeholder by scripts/sync-design.mjs: every export is typed loosely.',
    '// Replace this file with a hand-written declaration of the module API (it is then kept).',
    '/* eslint-disable @typescript-eslint/no-explicit-any */',
  ]
  for (const [name, kind] of names) {
    if (kind === 'function') lines.push(`export declare function ${name}(...args: any[]): any`)
    else if (kind === 'class') lines.push(`export declare class ${name} { constructor(...args: any[]); [key: string]: any }`)
    else lines.push(`export declare const ${name}: any`)
  }
  if (hasDefault) lines.push('declare const _default: any', 'export default _default')
  return `${lines.join('\n')}\n`
}

async function syncSystemMap() {
  const jsSrc = resolve(assets, 'system-map.js')
  if (!existsSync(jsSrc)) {
    console.log(`[sync-design] ${rel(jsSrc)} not found yet: lib/3d left as is`)
    return
  }
  const js = applyPatches('js', rewriteThreeImports(await readFile(jsSrc, 'utf8')))
  await write(resolve(app, 'lib/3d/system-map.js'), header(jsSrc, (t) => jsComment(t + patchedNote('js'))) + js)
  const dts = resolve(app, 'lib/3d/system-map.d.ts')
  const generated = existsSync(dts) && (await readFile(dts, 'utf8')).startsWith('// GENERATED placeholder')
  if (!existsSync(dts) || generated) await write(dts, looseDts(js))
  else {
    // a hand-written declaration is kept; say which exports it does not declare (or declares but are gone)
    const declared = new Set([...(await readFile(dts, 'utf8')).matchAll(/^export\s+(?:declare\s+)?(?:function|const|class|let)\s+([A-Za-z_$][\w$]*)/gm)].map((m) => m[1]))
    const exported = new Set(exportNames(js).names.keys())
    const missing = [...exported].filter((n) => !declared.has(n))
    const stale = [...declared].filter((n) => !exported.has(n))
    if (missing.length || stale.length) {
      console.warn(`[sync-design] ${rel(dts)} is out of date: not declared ${missing.join(', ') || '-'} · no longer exported ${stale.join(', ') || '-'}`)
    } else console.log(`[sync-design] ${rel(dts)} is hand-written: kept (declares every export)`)
  }

  const cssSrc = resolve(assets, 'system-map.css')
  if (existsSync(cssSrc)) {
    const css = applyPatches('css', await readFile(cssSrc, 'utf8'))
    await write(resolve(app, 'lib/3d/system-map.css'), header(cssSrc, (t) => cssComment(t + patchedNote('css'))) + css)
  }
}

async function syncDictionary() {
  const src = resolve(repo, 'docs/DATA-DICTIONARY.md')
  await write(resolve(app, 'public/DATA-DICTIONARY.md'), await readFile(src, 'utf8'))
}

await syncStyles()
await syncSystemMap()
await syncDictionary()
